var w = api.w, h = api.h, T = api.t;
var e = 0.5 - 0.5 * Math.cos(2 * Math.PI * T);
var base = h * 0.18;
var top = h * p.reach;
var front = h - (base + (top - base) * e);
for (var x = 0; x < w; x++) {
  var yc = Math.round(front + Math.sin(x * 0.45 + 2 * Math.PI * T) * p.wobble + Math.sin(x * 0.17 - 2 * Math.PI * T) * p.wobble * 0.6);
  if (yc >= h) continue;
  api.rect(x, yc, 1, h - yc, 3, 0.85 * p.intensity);
  var deep = yc + Math.round((h - yc) * 0.55);
  api.rect(x, deep, 1, h - deep, 5, 0.45 * p.intensity);
  api.px(x, yc, 0, p.intensity);
  api.px(x, yc + 1, 0, (0.2 + 0.5 * e) * p.intensity);
  for (var s = 0; s < 2; s++) {
    var r = api.rnd(x * 7 + s * 31);
    if (r < p.foam * 0.22) api.px(x, yc + 2 + Math.floor(r * 26), 0, 0.5 * p.intensity);
  }
}
var n = Math.round(p.drops);
for (var i = 0; i < n; i++) {
  var t0 = 0.30 + api.rnd(i) * 0.16;
  var u = (T - t0 + 1) % 1;
  if (u > 0.34) continue;
  var k = u / 0.34;
  var sx = api.rnd(i * 3 + 1) * w;
  var sy = h - (base + (top - base) * 0.85);
  var vy = (0.9 + api.rnd(i * 5 + 2) * 0.8) * p.lift;
  var dx = Math.round(sx + (api.rnd(i * 9 + 4) - 0.5) * 12 * k);
  var dy = Math.round(sy - vy * k * 11 + k * k * 24);
  var a = (1 - k) * Math.min(1, k * 5) * p.intensity;
  api.px(dx, dy, 0, a);
  if (api.rnd(i * 13 + 6) > 0.6) api.px(dx + 1, dy + 1, 2, a * 0.7);
}
